/**
 * Debug Validation Issue
 * Test to isolate validation middleware issue
 */

import { describe, it, expect, beforeEach } from '@jest/globals';
import request from 'supertest';

let app: any;

beforeEach(async () => {
  // Set required environment variables
  process.env.JWT_SECRET = 'test-jwt-secret-debug-validation';
  process.env.NODE_ENV = 'test';
  
  const appModule = await import('../src/index');
  app = appModule.app;
});

describe('Debug Validation', () => {
  it('should test registration with exact comprehensive test data', async () => {
    const testUser = {
      email: 'security-test@example.com',
      password: 'SecureTestPassword123!',
      name: 'Security Test User',
      role: 'teacher'
    };

    const uniqueEmail = `test-debug-${Date.now()}@example.com`;
    
    console.log('Testing registration with comprehensive test pattern...');
    
    const response = await request(app)
      .post('/api/auth/register')
      .send({
        email: uniqueEmail,
        password: testUser.password,
        name: testUser.name,
      });

    console.log('Debug validation response status:', response.status);
    console.log('Debug validation response body:', response.body);
    console.log('Debug validation response headers:', response.headers);

    expect(response.status).toBe(201);
    expect(response.body).toHaveProperty('user');
    expect(response.body).toHaveProperty('accessToken');
  });
});